import { motion } from "framer-motion";
import { ArrowRight, Sparkles, Target, Star, Heart, Mail, Lock, LogIn } from "lucide-react";
import HeroBackground from "@/components/HeroBackground";
import UserTypeCards from "@/components/UserTypeCards";
import FeaturesSection from "@/components/FeaturesSection";
import StatsSection from "@/components/StatsSection";
import HowItWorks from "@/components/HowItWorks";
import Footer from "@/components/Footer";
import Header from "@/components/Header";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useEffect, useState } from "react";
import { getUser, loginUser } from "@/lib/auth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";

const Index = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { toast } = useToast();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Check if user is logged in and redirect to dashboard
    const user = getUser();
    console.log("Index page: checking user", { hasUser: !!user, userName: user?.name });
    
    if (user) {
      console.log("Index page: redirecting to dashboard");
      navigate("/dashboard");
      return;
    }

    const qr = searchParams.get("qr");
    const source = searchParams.get("source");
    const ref = searchParams.get("ref");
    
    if (qr === "discount30" && source === "qrcode") {
      navigate(`/qr-register?qr=${qr}&source=${source}`);
    }
    
    if (ref) {
      localStorage.setItem("referralCode", ref);
      navigate(`/qr-register?ref=${ref}&source=referral`);
    }
  }, [searchParams, navigate]);

  const scrollToHowItWorks = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    const element = document.getElementById('how-it-works');
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleQuickLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const user = await loginUser({ contact: email.trim(), password: password.trim() });
      toast({
        title: "Успешный вход",
        description: "Добро пожаловать в систему!",
      });
      navigate("/dashboard");
    } catch (err) {
      toast({
        title: "Ошибка входа",
        description: "Неверный email или пароль",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen">
      <Header transparent />

      {/* Hero Section */}
      <section className="relative min-h-screen flex items-center justify-center px-4 overflow-hidden">
        <HeroBackground />
        <div className="relative z-10 text-center max-w-5xl mx-auto pt-16">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-full bg-card/15 backdrop-blur-lg border border-card/10 text-primary-foreground text-sm font-medium mb-8 shadow-lg"
          >
            <Sparkles className="w-4 h-4" />
            AI-платформа для вашего будущего
          </motion.div>

          <motion.h1
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.1 }}
            className="text-4xl md:text-6xl lg:text-7xl font-heading font-bold text-primary-foreground mb-6 leading-tight"
          >
            Определи своё{" "}
            <span className="text-gradient-gold">будущее</span>
            <br />
            уже сегодня
          </motion.h1>

          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.3 }}
            className="text-lg md:text-xl text-primary-foreground/80 max-w-2xl mx-auto mb-6"
          >
            Наш AI-алгоритм поможет определить твои навыки, подобрать профессию
            и найти идеальный университет — бесплатно, по гранту или на платной основе
          </motion.p>

          {/* Dream Section */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="mb-12"
          >
            <div className="inline-flex items-center gap-2 px-6 py-3 rounded-full bg-gradient-to-r from-amber-500/20 via-yellow-500/20 to-orange-500/20 backdrop-blur-md border border-amber-500/30 text-amber-100">
              <Star className="w-4 h-4 text-amber-400" />
              <span className="text-sm font-medium">Твоя мечта начинается здесь</span>
              <Heart className="w-4 h-4 text-rose-400" />
            </div>
            
            <motion.div 
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.6 }}
              className="mt-6 max-w-2xl mx-auto"
            >
              <p className="text-2xl md:text-3xl font-heading font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-yellow-200 to-amber-400 mb-3">
                Какая у тебя цель?
              </p>
              <p className="text-primary-foreground/70 text-base md:text-lg">
                Поступить на грант в топовый вуз? Получить престижную профессию? 
                <br className="hidden md:block" />
                Или стать частью глобального сообщества профессионалов?
              </p>
            </motion.div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.8 }}
            className="mb-8"
          >
            <div className="flex items-center justify-center gap-3">
              <Target className="w-5 h-5 text-primary-foreground/60" />
              <p className="text-primary-foreground/60 text-sm font-medium tracking-wider uppercase">
                Выбери, кто ты сегодня
              </p>
              <Target className="w-5 h-5 text-primary-foreground/60" />
            </div>
          </motion.div>

          <UserTypeCards />

          {/* Quick Login Form */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 1.2 }}
            className="mt-12 w-full max-w-md mx-auto"
          >
            <div className="glass rounded-3xl p-6 border border-card/20 shadow-card">
              <h3 className="text-xl font-heading font-bold text-foreground mb-4 text-center">
                Уже есть аккаунт?
              </h3>
              <form onSubmit={handleQuickLogin} className="space-y-4">
                <div>
                  <Label htmlFor="email" className="text-sm text-foreground/70">Email</Label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input
                      id="email"
                      type="email"
                      placeholder="your@email.com"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="pl-10 bg-background/50 border-border/50"
                      required
                    />
                  </div>
                </div>
                <div>
                  <Label htmlFor="password" className="text-sm text-foreground/70">Пароль</Label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input
                      id="password"
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="pl-10 bg-background/50 border-border/50"
                      required
                    />
                  </div>
                </div>
                <Button
                  type="submit"
                  disabled={loading || !email.includes("@") || password.length < 6}
                  className="w-full gap-2"
                >
                  {loading ? (
                    "Вход..."
                  ) : (
                    <>
                      <LogIn className="w-4 h-4" />
                      Быстрый вход
                    </>
                  )}
                </Button>
              </form>
              <div className="mt-4 text-center">
                <p className="text-sm text-muted-foreground">
                  Нет аккаунта?{" "}
                  <button
                    onClick={() => navigate("/register")}
                    className="text-primary hover:underline font-medium"
                  >
                    Зарегистрироваться
                  </button>
                </p>
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1.5 }}
            className="mt-16"
          >
            <a 
              href="#how-it-works" 
              onClick={scrollToHowItWorks}
              className="inline-flex items-center gap-2 text-primary-foreground/60 hover:text-primary-foreground transition-colors text-sm cursor-pointer"
            >
              Как это работает <ArrowRight className="w-4 h-4" />
            </a>
          </motion.div>
        </div>
      </section>

      <StatsSection />
      <HowItWorks />
      <FeaturesSection />
      <Footer />
    </div>
  );
};

export default Index;
